import {createLibrary,filterFilms,resumeTime} from './state.mjs';
const $=s=>document.querySelector(s);
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${{play:'<path d="m7 4 14 8-14 8z"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',list:'<path d="M9 6h11M9 12h11M9 18h11M4 6h.01M4 12h.01M4 18h.01"/>'}[name]||''}</svg>`;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const minutes=f=>`${Math.ceil(f.duration/60)} min`;
let films=[],library,query='',genre='All',baseView='home',modalReturn='#home',activeFilm=null,video=null,saveStamp=0,toastTimer,routeFrom='';
const genres=['All','Animation','Fantasy','Sci-Fi','Comedy','Adventure','Drama','Action'];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700);}
function meta(f){return `<div class="meta"><span>${f.year}</span><span class="dot"></span><span>${minutes(f)}</span><span class="dot"></span><span>${f.genres.join(' · ')}</span><span class="tag">HD</span></div>`;}
function saveButton(f,large=false){return `<button class="${large?'button secondary':'round'} ${library.has(f.id)?'saved':''}" data-action="save" data-id="${f.id}" aria-label="${library.has(f.id)?'Remove':'Add'} ${esc(f.title)} ${library.has(f.id)?'from':'to'} My List" aria-pressed="${library.has(f.id)}">${icon(library.has(f.id)?'check':'plus')}${large?`<span>${library.has(f.id)?'In My List':'My List'}</span>`:''}</button>`;}
function card(f,continuing=false){const p=library.progress(f.id);return `<article class="film-card"><div class="art"><img src="${f.image}" alt="" loading="lazy" width="640" height="400"><a class="card-link" href="#${continuing?'watch':'film'}=${f.id}" aria-label="${continuing?'Continue watching':'Details for'} ${esc(f.title)}"><span class="card-play">${icon('play','play-icon')}</span><span class="card-title">${esc(f.title)}</span></a></div><div class="card-info"><span class="card-meta">${f.genres[0]} <span aria-hidden="true">·</span> ${minutes(f)}</span>${saveButton(f)}</div>${continuing?`<div class="progress-bar" aria-label="${Math.round(p.time/p.duration*100)} percent watched"><span style="width:${Math.min(100,p.time/p.duration*100)}%"></span></div><div class="progress-note">${Math.ceil((p.duration-p.time)/60)} min left <button class="text-button" data-action="remove-progress" data-id="${f.id}" aria-label="Remove ${esc(f.title)} from Continue Watching">Remove</button></div>`:''}</article>`;}
function section(title,subtitle,collection,continuing=false){if(!collection.length)return '';return `<section class="section"><div class="section-title"><div><h2>${title}</h2><p>${subtitle}</p></div>${continuing?'':`<a href="#films">Explore all ${icon('arrow')}</a>`}</div><div class="row">${collection.map(f=>card(f,continuing)).join('')}</div></section>`;}
function chips(){return `<div class="chips" aria-label="Filter by genre">${genres.map(g=>`<button class="chip ${genre===g?'active':''}" data-action="genre" data-genre="${g}" aria-pressed="${genre===g}">${g==='All'?'For you':g}</button>`).join('')}</div>`;}
function home(){const f=films[0];return `<section class="hero" aria-labelledby="hero-title"><img class="hero-image" src="${f.image}" alt="A young shepherd holding a glowing staff in Spring" fetchpriority="high" width="1280" height="720"><div class="hero-content"><span class="eyebrow"><span class="red-line"></span>TONIGHT’S LITTLE ESCAPE</span><h1 id="hero-title">Spring</h1>${meta(f)}<p class="hero-description">A young shepherd. An ancient forest. A world waiting to wake.<br>Some journeys change the season.</p><div class="actions"><a class="button primary" href="#watch=spring">${icon('play','play-icon')} ${resumeTime(library.progress('spring'))?'Resume film':'Watch now'}</a><a class="button secondary" href="#film=spring">${icon('info')} More info</a></div></div><div class="hero-bottom">${icon('lock')} NO ACCOUNT. JUST GREAT FILMS.</div><div class="hero-caption">A FILM BY ANDY GORALCZYK</div></section><div class="content home-content"><div class="collection-bar"><h2>Find your next escape</h2>${chips()}</div>${section('Pick up where you left off','Your next scene is waiting.',library.continueWatching(),true)}${section('Small films. Big worlds.','Handpicked stories worth getting lost in.',films.slice(1,6))}<div class="feature-band"><div class="feature-copy"><span class="eyebrow">THE OPEN CINEMA COLLECTION</span><h2>Made with imagination.<br>Shared with everyone.</h2><p>Extraordinary films from independent minds. Free to watch, with every creator credited.</p><a href="#about">Meet the films behind NetFlex ${icon('arrow')}</a></div><div class="feature-image"><img src="assets/cosmos-laundromat.webp" alt="A fantastical landscape from Cosmos Laundromat" loading="lazy" width="1280" height="720"></div></div>${section('A little out of this world','Other realities. Unforgettable adventures.',[films[6],films[3],films[7],films[9],films[0]])}</div>`;}
function browse(view){const list=view==='list'?library.list():films;const shown=filterFilms(list,query,genre);const title=query?`Results for “${esc(query)}”`:view==='list'?'Your next movie night.':'A world of stories.';return `<div class="content browse-page"><div class="page-heading"><span class="eyebrow">${view==='list'?'MY LIST':'THE COLLECTION'}</span><h1>${title}</h1><p>${query?`${shown.length} ${shown.length===1?'film':'films'} found`:view==='list'?'Your favourites, saved in this browser.':'A small, carefully chosen collection. Every film is free to watch.'}</p></div><div class="collection-bar">${chips()}<span class="fine">${shown.length} ${shown.length===1?'film':'films'}</span></div>${shown.length?`<div class="grid">${shown.map(f=>card(f)).join('')}</div>`:`<div class="empty">${icon(view==='list'&&!query?'list':'search')}<h2>${view==='list'&&!query&&!list.length?'Make room for a good story.':'No films found.'}</h2><p>${view==='list'&&!query&&!list.length?'Tap + on any film to save it here for later.':'Try another title or clear your filters.'}</p><button class="button primary" data-action="reset-filters">${view==='list'&&!list.length?'Discover films':'Clear filters'}</button></div>`}</div>`;}
function about(){return `<div class="content browse-page"><div class="page-heading"><span class="eyebrow">OPEN FILMS. OPEN POSSIBILITIES.</span><h1>Good stories are for sharing.</h1></div><div class="about-intro"><p>NetFlex is a personal cinema project by Joyson, reimagined from a desktop video player for the web. Browse, press play, and keep a little list of what you love. No account needed.</p><p>This collection celebrates open films made by Blender’s artists and storytellers. Each film streams from Blender’s servers with its original credits. Artwork is from the films’ official project pages, cropped for this interface. Film playback is unmodified.</p><p>Your list and progress stay in this browser. NetFlex does not collect visitor analytics. Streaming and hosting providers receive normal requests to deliver the site and films. Availability and playback depend on those providers and your connection.</p><p>Content notes are editorial guidance, not official age ratings. Some films contain mature themes; check a film’s details before watching.</p></div><h2 class="credits-title">The films & their makers</h2><div class="credits">${films.map(f=>`<article class="credit"><h2>${f.title}</h2><p>Directed by ${f.director} · ${f.year}</p><p>${f.credit} · <a href="${f.sourcePage}" target="_blank" rel="noopener noreferrer">Official project & credits</a></p><p><a href="${f.licenseUrl}" target="_blank" rel="noopener noreferrer">${f.license}</a> · <a href="${f.videoPage}" target="_blank" rel="noopener noreferrer">Original film</a></p></article>`).join('')}</div></div>`;}
function render(){if(!library)return;$('#main').innerHTML=query||baseView==='films'||baseView==='list'||genre!=='All'?browse(baseView):baseView==='about'?about():home();$('#list-count').textContent=library.list().length;document.querySelectorAll('[data-nav]').forEach(el=>{const on=el.dataset.nav===baseView;el.classList.toggle('active',on);if(on)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});document.title=baseView==='list'?'My List — NetFlex':baseView==='about'?'Film credits — NetFlex':'NetFlex — A world of stories';}
function details(f){const d=$('#detail-dialog');d.innerHTML=`<button class="round close" data-action="close" aria-label="Close film details">×</button><div class="detail-art"><img src="${f.image}" alt="${esc(f.title)} film artwork"><div class="detail-heading"><h2>${f.title}</h2><div class="actions"><a class="button primary" href="#watch=${f.id}">${icon('play','play-icon')} ${resumeTime(library.progress(f.id))?'Resume':'Watch film'}</a>${saveButton(f,true)}</div></div></div><div class="detail-body">${meta(f)}<p>${f.description}</p><div class="detail-facts"><span><b>Director:</b> ${f.director}</span><span><b>Content note:</b> ${f.advisory}</span><span><b>Credits:</b> ${f.credit} · <a href="${f.sourcePage}" target="_blank" rel="noopener noreferrer">Official project</a></span><span><b>Licence:</b> <a href="${f.licenseUrl}" target="_blank" rel="noopener noreferrer">${f.license}</a></span><span class="fine">Streams from Blender’s video servers. Film unmodified; artwork cropped for display.</span></div></div>`;d.showModal();document.title=`${f.title} — NetFlex`;}
function record(){if(video&&activeFilm&&Number.isFinite(video.duration)&&video.currentTime>0){library.record(activeFilm.id,video.currentTime,video.duration);saveStamp=Date.now();}}
function stopPlayer(){if(video){record();video.pause();video.removeAttribute('src');video.load();video=null;activeFilm=null;}$('#player-dialog').close();$('#player-dialog').innerHTML='';}
function watch(f){stopPlayer();activeFilm=f;const p=$('#player-dialog');p.innerHTML=`<div class="player-top"><div><h2>${f.title}</h2><p>${f.year} · ${minutes(f)} · ${f.advisory}</p></div><button class="round close" data-action="close" aria-label="Close player">×</button></div><div class="player-wrap"><video controls playsinline preload="metadata" poster="${f.image}" aria-label="${esc(f.title)} video player"></video></div><div id="playback-error" class="player-error" hidden><h3>This stream couldn’t load.</h3><p>Try again or select a lower quality. You can also watch on the original film page.</p><button class="button primary" data-action="retry">Try again</button><a class="button secondary" href="${f.videoPage}" target="_blank" rel="noopener noreferrer">Open original film</a></div><div class="player-controls"><button class="text-button" data-action="rewind" aria-label="Rewind 10 seconds">↶ 10 seconds</button><button class="text-button" data-action="forward" aria-label="Forward 10 seconds">10 seconds ↷</button><button class="text-button" data-action="restart">Start over</button><label>Quality <select id="quality" aria-label="Video quality">${f.sources.map(s=>`<option value="${esc(s.url)}" ${s.url===f.defaultSource?'selected':''}>${s.label}</option>`).join('')}</select></label></div><div class="player-credit">${f.credit} · Directed by ${f.director} · <a href="${f.licenseUrl}" target="_blank" rel="noopener noreferrer">${f.license}</a> · Progress saved in this browser.</div>`;p.showModal();video=p.querySelector('video');video.addEventListener('timeupdate',()=>{if(Date.now()-saveStamp>4000)record();});video.addEventListener('pause',record);video.addEventListener('ended',()=>{record();toast('Finished. Find your next story in the collection.');});video.addEventListener('error',()=>{$('#playback-error').hidden=false;});const time=resumeTime(library.progress(f.id));loadSource(f.defaultSource,time,true);document.title=`Watching ${f.title} — NetFlex`;}
function loadSource(url,time,autoplay){const v=video;$('#playback-error').hidden=true;v.addEventListener('loadedmetadata',()=>{if(v!==video)return;if(time>0&&Number.isFinite(v.duration))v.currentTime=Math.min(time,Math.max(0,v.duration-1));if(autoplay)v.play().catch(()=>{/* Native controls remain usable if autoplay is blocked. */});},{once:true});v.src=url;v.load();}
function route(){const hash=location.hash.slice(1)||'home';if(hash==='main'){$('#main').focus();return;}const match=hash.match(/^(film|watch)=([a-z0-9-]+)$/);if(match){const f=films.find(f=>f.id===match[2]);if(!f){location.hash='films';toast('That film is not in the collection.');return;}if(!routeFrom.match(/^#(film|watch)=/))modalReturn=routeFrom||'#home';$('#detail-dialog').close();stopPlayer();if(!$('#main .hero')&&!$('#main .browse-page'))render();match[1]==='film'?details(f):watch(f);document.body.style.overflow='hidden';}else{stopPlayer();$('#detail-dialog').close();document.body.style.overflow='';baseView=['home','films','list','about'].includes(hash)?hash:'home';if(routeFrom!==`#${hash}`){query='';genre='All';$('#search').value='';}render();window.scrollTo({top:0,behavior:'instant'});}routeFrom=location.hash;}
function closeModal(){location.hash=modalReturn||'#home';}
function privacy(){const p=$('#privacy-dialog');$('#storage-status').textContent=library.persistent?'Browser storage is available.':'Browser storage is blocked. Your list will last only for this visit.';$('#clear-feedback').textContent='';$('#clear-data').textContent='Clear my watchlist & history';$('#clear-data').dataset.confirm='';p.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!library)return;const id=b.dataset.id;switch(b.dataset.action){case 'save':library.toggle(id);const title=films.find(f=>f.id===id).title;toast(`${library.has(id)?'Added to':'Removed from'} My List: ${title}`);render();if($('#detail-dialog').open){$('#detail-dialog').close();details(films.find(f=>f.id===id));}break;case 'genre':genre=b.dataset.genre;render();if(baseView==='home'&&genre!=='All')window.scrollTo({top:0,behavior:'instant'});break;case 'reset-filters':query='';genre='All';$('#search').value='';if(baseView==='list'&&!library.list().length)location.hash='films';else render();break;case 'remove-progress':library.removeProgress(id);render();toast('Removed from Continue Watching');break;case 'close':closeModal();break;case 'privacy':privacy();break;case 'close-privacy':$('#privacy-dialog').close();break;case 'rewind':if(video)video.currentTime=Math.max(0,video.currentTime-10);break;case 'forward':if(video&&Number.isFinite(video.duration))video.currentTime=Math.min(video.duration,video.currentTime+10);break;case 'restart':if(video){video.currentTime=0;library.removeProgress(activeFilm.id);video.play().catch(()=>{});}break;case 'retry':if(video)loadSource(video.currentSrc,video.currentTime||resumeTime(library.progress(activeFilm.id)),true);break;}});
$('#search').addEventListener('input',e=>{query=e.target.value;render();if(query)window.scrollTo({top:0,behavior:'instant'});});
$('#device-button').addEventListener('click',()=>library&&privacy());
$('#clear-data').addEventListener('click',e=>{if(e.target.dataset.confirm!=='yes'){e.target.dataset.confirm='yes';e.target.textContent='Yes, clear my saved data';$('#clear-feedback').textContent='This removes your list and viewing progress from this browser.';return;}library.clear();render();e.target.dataset.confirm='';e.target.textContent='Clear my watchlist & history';$('#clear-feedback').textContent='Your watchlist and viewing history have been cleared.';toast('Your browser collection has been reset.');});
document.addEventListener('change',e=>{if(e.target.id==='quality'&&video){const time=video.currentTime;const playing=!video.paused;record();loadSource(e.target.value,time,playing);}});
for(const id of ['detail-dialog','player-dialog']){$('#'+id).addEventListener('cancel',e=>{e.preventDefault();closeModal();});$('#'+id).addEventListener('click',e=>{if(e.target===$('#'+id)){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});}
document.addEventListener('keydown',e=>{if(!video||e.target.matches('input,select,button,a')||e.target===video)return;if(e.code==='Space'){e.preventDefault();video.paused?video.play().catch(()=>{}):video.pause();}else if(e.key==='ArrowLeft'){e.preventDefault();video.currentTime=Math.max(0,video.currentTime-10);}else if(e.key==='ArrowRight'&&Number.isFinite(video.duration)){e.preventDefault();video.currentTime=Math.min(video.duration,video.currentTime+10);}});
window.addEventListener('hashchange',route);window.addEventListener('pagehide',record);document.addEventListener('visibilitychange',()=>{if(document.hidden)record();});
async function init(){try{const res=await fetch('catalog.json');if(!res.ok)throw Error('catalog');films=await res.json();if(!Array.isArray(films)||!films.length)throw Error('empty');let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('unavailable');},setItem(){throw Error('unavailable');}};}library=createLibrary(storage,films);route();if(!library.persistent)toast('Browser storage is blocked. Saves last for this visit only.');}catch{$('#main').innerHTML='<div class="loading"><h1>The cinema couldn’t load.</h1><p>Check your connection, then try again.</p><button id="reload" class="button primary">Try again</button></div>';$('#reload').addEventListener('click',()=>location.reload());}}
init();
